from __future__ import annotations

import base64
import gzip
import hashlib
import json
import os
import shutil
import subprocess
import sys
import traceback
from datetime import datetime
from pathlib import Path

PROJECT = Path(os.environ.get("PHOCAP_PROJECT", r"C:\PhoCap")).resolve()
APP = PROJECT / "app"

EXPECTED_HASHES = {'app/templates/partials/dropdown_menu_v1.html': '48d809fa7d86aa857086080c5d5025781b4b2bdcb40ae24b92d740497975639b', 'app/routers/users.py': 'ab4082b7a7f6c7896509b960b9a1064ef70fa343b70989ced450f118a66c2c62', 'app/routers/schools.py': 'b5b2846167fa181241c9eaae3d8010ed982aa5b383989c8d82a62eff5968140a', 'app/templates/users/list.html': 'c873a8564a195ac6cddb1e1600a6af9c703ab1306e30443006a287161c553fb0', 'app/templates/schools/list.html': '9fa98b693305f3df0082c9e7d2ba3ba11fca45b0642113e5b879acaebbc36ded'}
PAYLOAD = {'app/templates/partials/dropdown_menu_v1.html': '', 'app/routers/users.py': '', 'app/routers/schools.py': '', 'app/templates/users/list.html': '', 'app/templates/schools/list.html': ''}

STAMP = datetime.now().strftime("%Y%m%d_%H%M%S")
BACKUP = PROJECT / "exports" / f"backup_bai_13b_6_menu_chinh_xac_{STAMP}"
MANIFEST = BACKUP / "manifest.json"


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def preflight() -> None:
    print("Kiểm tra đúng 5 tệp mã nguồn mà bạn vừa gửi...")
    mismatches = []

    for rel, expected in EXPECTED_HASHES.items():
        path = PROJECT / rel
        if not path.exists():
            mismatches.append(f"THIẾU: {rel}")
            continue

        actual = sha256(path)
        if actual != expected:
            mismatches.append(
                f"KHÁC BẢN ĐÃ GỬI: {rel}\n"
                f"  expected={expected}\n"
                f"  actual  ={actual}"
            )

    model_file = APP / "report_input_models.py"
    if not model_file.exists():
        mismatches.append("THIẾU: app/report_input_models.py")
    else:
        model_text = model_file.read_text(encoding="utf-8-sig")
        if "class SchoolNetworkYearData" not in model_text:
            mismatches.append(
                "app/report_input_models.py chưa có class SchoolNetworkYearData"
            )

    if mismatches:
        print("")
        print("DỪNG AN TOÀN. MÃ NGUỒN TRÊN MÁY KHÔNG CÒN ĐÚNG BẢN ZIP VỪA GỬI.")
        for item in mismatches:
            print(" -", item)
        print("")
        print("Không có tệp nào bị thay đổi.")
        raise RuntimeError("Preflight không đạt.")


def backup_files() -> list[dict]:
    BACKUP.mkdir(parents=True, exist_ok=False)
    manifest = []

    for rel in PAYLOAD:
        src = PROJECT / rel
        existed = src.exists()
        manifest.append({"path": rel, "existed": existed})

        if existed:
            dst = BACKUP / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)

    MANIFEST.write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return manifest


def restore_files(manifest: list[dict]) -> None:
    for item in reversed(manifest):
        target = PROJECT / item["path"]
        if item["existed"]:
            src = BACKUP / item["path"]
            if src.exists():
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, target)
        elif target.exists() and target.is_file():
            target.unlink()


def write_files() -> None:
    for rel, encoded in PAYLOAD.items():
        target = PROJECT / rel
        raw = gzip.decompress(base64.b64decode(encoded))
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(raw)


def verify() -> None:
    # Python
    for rel in [
        "app/routers/users.py",
        "app/routers/schools.py",
    ]:
        subprocess.run(
            [sys.executable, "-m", "py_compile", str(PROJECT / rel)],
            cwd=PROJECT,
            check=True,
        )

    # Jinja
    from jinja2 import Environment, FileSystemLoader
    env = Environment(loader=FileSystemLoader(str(APP / "templates")))
    for name in [
        "partials/dropdown_menu_v1.html",
        "users/list.html",
        "schools/list.html",
    ]:
        env.get_template(name)

    menu = (APP / "templates" / "partials" / "dropdown_menu_v1.html").read_text(
        encoding="utf-8-sig"
    )
    required_menu = [
        "TK trường Mầm non",
        "TK trường Tiểu học",
        "TK trường THCS",
        "Danh mục trường Mầm non",
        "Danh mục trường Tiểu học",
        "Danh mục trường THCS",
    ]
    for marker in required_menu:
        if marker not in menu:
            raise RuntimeError(f"Thiếu menu sau cài: {marker}")

    users = (APP / "routers" / "users.py").read_text(encoding="utf-8-sig")
    schools = (APP / "routers" / "schools.py").read_text(encoding="utf-8-sig")

    for marker in [
        "BAI_13B_6_V1_4_TAI_KHOAN_TRUONG_THEO_CAP",
        "SchoolNetworkYearData.level_code == school_level",
        'cap: str = Query(default="")',
    ]:
        if marker not in users:
            raise RuntimeError(f"Kiểm tra users.py không đạt: {marker}")

    for marker in [
        "BAI_13B_6_V1_4_DANH_MUC_TRUONG_THEO_CAP",
        "SchoolNetworkYearData.level_code == level_code",
        "cap: str | None = Query(default=None)",
    ]:
        if marker not in schools:
            raise RuntimeError(f"Kiểm tra schools.py không đạt: {marker}")


def clear_cache() -> None:
    for cache in APP.rglob("__pycache__"):
        if cache.is_dir():
            shutil.rmtree(cache, ignore_errors=True)


def main() -> int:
    print("=" * 96)
    print("BÀI 13B-6 - SỬA MENU CHÍNH XÁC THEO 5 TỆP MÃ NGUỒN BẠN VỪA GỬI")
    print("=" * 96)
    print("")
    print("Bản này KHÔNG dựa vào các bộ cài FINAL-2A / FINAL-2B trước.")
    print("Nó thay trực tiếp đúng 5 tệp hiện tại đã được bạn đóng gói gửi lên.")
    print("")
    print("SẼ CÓ:")
    print("  1.1.3. TK trường Mầm non")
    print("  1.1.4. TK trường Tiểu học")
    print("  1.1.5. TK trường THCS")
    print("  1.2.2. Danh mục trường Mầm non")
    print("  1.2.3. Danh mục trường Tiểu học")
    print("  1.2.4. Danh mục trường THCS")
    print("")
    print("DANH SÁCH THỰC TẾ CŨNG ĐƯỢC LỌC THEO CẤP HỌC, KHÔNG CHỈ ĐỔI TÊN MENU.")
    print("")

    preflight()
    manifest = backup_files()

    try:
        write_files()
        verify()
        clear_cache()

        print("")
        print("CAI DAT BAI 13B-6 MENU CHINH XAC THANH CONG")
        print("Backup:", BACKUP)
        print("")
        print("Khởi động lại Uvicorn và nhấn Ctrl+F5 trên Chrome.")
        return 0

    except Exception:
        traceback.print_exc()
        print("")
        print("CÓ LỖI - ĐANG KHÔI PHỤC TỰ ĐỘNG 5 TỆP...")
        restore_files(manifest)
        print("ĐÃ KHÔI PHỤC VỀ TRƯỚC BẢN SỬA MENU.")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
